# Operations (NREMT EMR test plan, 2025: 10% to 14%). Job tasks: ensure equipment is in proper
# working order; ensure sufficient medication and supplies; ensure documentation is complete;
# ensure the well-being of self and other responders. Also medical oversight, consent, refusal,
# privacy and incident command as they bear on those tasks. Legal items stay general: consent,
# Good Samaritan and reporting rules vary by state. Privacy follows the HIPAA Privacy Rule
# (45 CFR 164). Incident command follows the National Incident Management System (FEMA).
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Equipment check", "When should you check your AED and oxygen supply?",
      ["At the start of every shift", "Only after a call where you used them", "Once a year at the agency's equipment inspection", "Only when a warning light flashes on it"],
      "A daily or start-of-shift check finds a dead battery, expired pads or an empty cylinder before a patient needs them."),
    S(1, 2, "Documentation", "Which entry belongs in a patient care report?",
      ["Patient states pain is 8 out of 10", "Patient seemed to be faking the pain to us", "Patient was rude, as usual", "Patient probably drinks too much, per neighbors"],
      "Patient states pain is 8 out of 10 is objective. Reports should be objective: what you saw, heard and did, and the patient's own words in quotes. Opinions and labels do not belong and can cause legal trouble."),
    S(1, 2, "Consent", "An unresponsive adult is found after a fall. On what basis can you treat him?",
      ["Implied consent", "Expressed consent", "Informed refusal", "A court order from a judge"],
      "When a patient cannot give consent and needs emergency care, the law assumes a reasonable person would want treatment. This is implied consent."),
    S(1, 3, "Refusal", "An alert, oriented adult with a cut hand refuses care after you explain the risks. What should you do?",
      ["Respect it, document it and advise calling back", "Treat him anyway, since he is injured and bleeding", "Leave without a word", "Call police to force treatment on the patient"],
      "A competent adult may refuse care. Make sure he understands the risks, try to persuade him, document the refusal and tell him to call back if he changes his mind."),
    S(1, 2, "Privacy", "A neighbor asks what is wrong with the patient you just treated. What should you say?",
      ["That you cannot share patient information", "The diagnosis, since a neighbor is like family", "Only the patient's medicines", "Whatever the patient's family allows"],
      "Patient information is private. Share it only with those involved in the patient's care or as the law requires, not with curious neighbors."),
    M(1, 2, "Responder well-being", "Which steps help responders cope after a very hard call? Select two.",
      ["Talking with peers or a support program", "Getting rest and regular meals", "Avoiding all talk about the call", "Drinking alcohol to sleep", "Working extra shifts back to back"],
      "Peer support, employee assistance programs, sleep and healthy routines help after a hard call. Bottling it up, alcohol and overwork make stress worse."),
    O(1, 2, "Stopping oxygen", "Put the steps for stopping oxygen after a patient no longer needs it in order.",
      ["Remove the device from the patient", "Close the cylinder valve", "Let the gauge fall to zero", "Turn the flowmeter off"],
      "Take the device off the patient first, then close the cylinder valve, let the oxygen left in the regulator bleed out until the gauge reads zero, and turn the flowmeter off."),
    # ---------- Practice Test 2 ----------
    S(2, 2, "Medical direction", "What is offline medical direction?",
      ["Written protocols and standing orders", "A doctor's orders by radio", "A nurse's advice by phone from the hospital", "Instructions read out by the dispatcher on the radio"],
      "Offline medical direction is the set of written protocols, standing orders and training approved by the medical director. Online direction is real-time orders by radio or phone."),
    S(2, 2, "Late entry", "After you submit a report, you remember a finding you left out. What should you do?",
      ["Add a dated late entry or addendum", "Change the original entry quietly", "Leave it out to avoid confusion", "Start a new report and delete the first"],
      "Follow your agency's process for a late entry or addendum, dated and signed, that adds the finding. Never change or delete the original record."),
    S(2, 2, "Abandonment", "You start care for a patient. Which act could count as abandonment?",
      ["Leaving before an equal or higher level takes over", "Handing off to an arriving EMT", "Staying with the patient until the ambulance leaves", "Asking a paramedic who arrives to take over"],
      "Once you begin care, you must continue until you hand off to someone with equal or higher training. Walking away before then is abandonment."),
    S(2, 2, "Minor consent", "A 10-year-old was hurt at soccer and no parent can be reached. She needs care now. What applies?",
      ["Implied consent for emergency care", "No care until a parent agrees", "Her coach must sign for her", "Only the child's own consent"],
      "Minors usually need a parent's consent, but when a child needs emergency care and no parent can be reached, implied consent allows treatment. Keep trying to reach the parent."),
    X(2, 2, "Incident command", "Match each role to its job under the Incident Command System.",
      ["Sets objectives for the whole incident", "Directs patient sorting", "Gets supplies and equipment", "Gives information to the media"],
      ["Incident commander", "Triage officer", "Logistics", "Public information officer"], [0, 1, 2, 3],
      "The incident commander leads and sets objectives, triage sorts patients, logistics finds supplies and equipment, and the public information officer speaks to the media."),
    S(2, 2, "Supply inventory", "After a call you used the last two pairs of gloves in your kit. What should you do?",
      ["Restock before the next call", "Wait until the weekly equipment check", "Borrow from the ambulance later", "Use bare hands on the next call"],
      "Restock right after a call so the next patient does not meet an empty kit. Ensuring enough supplies is part of an EMR's job."),
    S(2, 3, "Mandatory reporting", "While treating a child, you notice bruises of different ages and an unlikely story. What should you do?",
      ["Report your concern as your state requires", "Accuse the parents on scene and leave with the child", "Ignore it, since you are not a police officer", "Ask the child to keep it a secret from the parents"],
      "Signs of possible abuse must be reported to the proper authority as state law requires. Stay professional with the family, document what you saw and heard, and pass your concern on at handoff."),
    # ---------- Drill only ----------
    S(0, 2, "Duty to act", "When does an EMR have a duty to act?",
      ["While on duty and called to respond", "Whenever they see any accident, on or off duty", "Only when paid by the patient", "Only with a doctor present"],
      "On duty, an EMR has a legal duty to respond and give care. Off duty, rules vary by state, and Good Samaritan laws may protect people who help in good faith."),
    S(0, 2, "Scope of practice", "What defines what an EMR may do on a call?",
      ["State law, medical direction and protocols", "Whatever the patient asks for", "Whatever a bystander on scene suggests", "Anything learned from a training video online"],
      "Each state sets the legal scope of practice, using the national model as a guide, and the medical director sets local protocols. Act only within both."),
    S(0, 2, "Exposure report", "A used needle sticks your hand during a call. What should you do?",
      ["Wash the site and report it at once", "Wait to see if you feel sick", "Keep it quiet to avoid the extra paperwork", "Cover it and report it at next month's meeting"],
      "Wash the area with soap and water and report the exposure right away so testing and preventive treatment can start in time."),
    S(0, 2, "Sharps", "Why should you never recap a used needle by hand?",
      ["Recapping causes many needlesticks", "The cap must stay sterile", "Recapped needles cannot be counted", "It slows down the call too much"],
      "Recapping by hand is a common cause of needlestick injuries. Drop used sharps straight into a puncture-resistant sharps container."),
    S(0, 2, "Cleaning equipment", "A BVM mask is soiled with saliva after a call. What should happen to it?",
      ["Follow your agency's cleaning rules", "Wipe it on your sleeve and reuse it", "Leave it in the kit as is", "Rinse it with tap water only"],
      "Follow your agency's rules for single-use items and for cleaning and disinfecting reusable gear. Wear gloves while cleaning."),
    S(0, 2, "Radio communication", "Which radio message is best when calling for an ambulance?",
      ["Brief, clear facts in plain language", "Every detail of the history", "Codes only you understand", "Jokes to calm the crew"],
      "Keep radio traffic short and clear: location, number of patients, their condition and what you need. Plain language avoids confusion between agencies."),
    S(0, 2, "Privacy", "Which use of patient information is allowed under HIPAA?",
      ["Sharing findings with the receiving hospital", "Posting a photo of the scene online without names", "Telling friends about the call", "Describing the patient to the press at the scene"],
      "Sharing information with others caring for the patient is permitted. Posting scene photos or telling friends or the media is not."),
    S(0, 2, "Patient refusal", "A patient who refuses care is slurring his words and smells of alcohol. What should you consider?",
      ["He may not be able to refuse safely", "His refusal is always valid if he signs the form", "You must leave at once without a signature", "You can restrain him yourself until he agrees"],
      "A valid refusal needs a patient who understands the risks. Intoxication, head injury or low blood sugar can impair that. Get medical direction and police help as your protocols say."),
    S(0, 2, "Stress", "Which is a warning sign of growing stress in a responder?",
      ["Trouble sleeping and irritability", "Steady appetite and sleep", "Enjoying time off with friends and family", "Normal interest in hobbies and family"],
      "Sleep problems, irritability, withdrawal and loss of interest can signal stress building up. Seek support early."),
    M(0, 2, "Documentation", "What should a patient care report include? Select three.",
      ["Times of key events and care", "Vital signs and findings", "The care you gave and the response", "Your opinion of the family", "Rumors from bystanders", "Your guess at blame for the crash"],
      "A good report records times, findings, vital signs, the care given and how the patient responded. Opinions, rumors and blame do not belong."),
    O(0, 2, "Arriving at a multiple-patient scene", "Put the first actions of the first unit at a large incident in order.",
      ["Size up the scene", "Establish command", "Request more resources", "Begin triage"],
      "The first unit sizes up the scene, takes command, calls for what is needed and then starts triage so care reaches the right patients first."),
    S(0, 2, "Vehicle safety", "Why should you wear a seat belt when riding in the back of an ambulance?",
      ["Crashes can throw unbelted riders", "It is only a rule for drivers, not crew", "It speeds up the trip", "It keeps the patient calm during the ride"],
      "Unrestrained crew members are badly hurt in ambulance crashes. Stay belted whenever you can and secure loose equipment."),
    S(0, 2, "Advance directive", "A family shows you a valid do not resuscitate order for a patient in cardiac arrest. What should you do?",
      ["Follow the order and your local protocol", "Start CPR anyway every time", "Ignore it unless a doctor is present on scene", "Ask a bystander at the scene to decide for you"],
      "A valid DNR order or similar form tells you the patient's wishes. Follow it as your state and local protocols direct; if you doubt it is valid, begin care and seek medical direction."),
    S(0, 2, "Restocking oxygen", "Your oxygen cylinder gauge reads very low after a call. What should you do?",
      ["Replace it before the next call", "Keep using it until it is empty", "Store it with the full cylinders for later", "Mark it full to save time"],
      "Replace a low cylinder right away and mark the empty one so it is not grabbed by mistake. A cylinder that runs out mid-call puts the patient at risk."),
]
